using Mutagen.Bethesda.Plugins;
using Mutagen.Bethesda.Plugins.Binary.Headers;
using Mutagen.Bethesda.Plugins.Binary.Streams;
using Mutagen.Bethesda.Plugins.Meta;
using Mutagen.Bethesda.Starfield;
using Shouldly;
using Xunit;
using static Mutagen.Bethesda.UnitTests.Plugins.Records.Starfield.StarfieldTestRecords;

namespace Mutagen.Bethesda.UnitTests.Plugins.Records.Starfield;

// Raw or signature-named component fields get xEdit's names and types (wbDefinitionsSF1 base form components):
// - Activity ATAN is the Activity Type ("Kill", "Craft" ...).
// - Animation graph ENAM is the empty marker Controls Base Skeleton (2 in Starfield.esm, both 0 bytes).
// - Object window filter: INTV is the Count of the FLTR filters that follow (2,778 counts, all 1), now a counted list.
// - Display case items: Unknown1 is the Exclusion Filter Keyword (a FormID read as a number; null in all 422),
//   Unknown2 is the Number (all 1).
// - Spaceship equipment ESSF is the 4-byte Essential bool (1,522: 0 or 1).
// - Crowd: CDND Density; CDNS is the Populations Count (46 entries in 24 crowds match the counts; kept as a plain
//   UInt32: Loqui's counted list splits these items wrongly); STRV Name and FLTV Population Scale in each entry.
// - World space overlay: SNAM Star System ID and PNAM Planet ID (Int32; -1, 0 and IDs).
// - Adaptive trigger: WFIR Fire Effect and WAIM ADS Effect, each an unused byte (always 0), Start Position, End
//   Position and Strength.
// - Blueprint BODV Color 1-3 were marked unknown; the names were already xEdit's.
// Each test reads a whole record from Starfield.esm with both readers and writes it back byte for byte, leaving out
// the localized strings (FULL, DESC), which the test writer can't write back as string IDs.
public class ComponentFieldNameM2Tests
{
    private static readonly RecordType[] Localized = { new("FULL"), new("DESC") };

    private static byte[] WithoutLocalized(ReadOnlySpan<byte> content)
    {
        var ret = new MemoryStream();
        var pos = 0;
        while (pos < content.Length)
        {
            var type = new RecordType(BitConverter.ToInt32(content.Slice(pos, 4)));
            var len = BitConverter.ToUInt16(content.Slice(pos + 4, 2));
            if (!Localized.Contains(type)) ret.Write(content.Slice(pos, 6 + len));
            pos += 6 + len;
        }
        return ret.ToArray();
    }

    private static void WritesBack(Action<MutagenWriter> write, string hex)
    {
        var written = GameConstants.Starfield.MajorRecord(Write(write));
        WithoutLocalized(written.Content).ShouldBe(WithoutLocalized(Hex(hex)));
    }

    private static T Component<T>(IEnumerable<IAComponentGetter> components) => components.OfType<T>().Single();

    // Skill_HeavyWeaponCertification (147E38:Starfield.esm)
    private const string HeavyWeapons = "";
    // CageGen_DoorLG02 (1805BC:Starfield.esm)
    private const string CageDoor = "";
    // RIR07_ExecutiveFurnitureLocRefType (0151B4:Starfield.esm)
    private const string FurnitureLocRefType = "";
    // Loot_Display_WeaponsCase_Rifles_Common_100YearOld (005D2C:Starfield.esm)
    private const string RifleCase = "";
    // MQ207_Scorpius_Custom (050CEE:Starfield.esm)
    private const string Scorpius = "";
    // CrowdRegion_NewAtlantis03 (00D5A8:Starfield.esm)
    private const string Crowd = "";
    // OverlayPOIBiomeDenVolcanicRough01 (002D62:Starfield.esm)
    private const string Overlay = "";
    // WeaponTypeDisplay_ElectromagneticRifle (1C84DD:Starfield.esm)
    private const string Electromagnetic = "";

    [Fact]
    public void Activity_Type()
    {
        foreach (var perk in ReadBoth<IPerkGetter>(Record("PERK", Hex(HeavyWeapons)), f => Perk.CreateFromBinary(f), (s, p) => PerkBinaryOverlay.PerkFactory(s, p)))
        {
            var activities = perk.Ranks.SelectMany(r => r.Activities ?? (IEnumerable<IActivityGetter>)Array.Empty<IActivityGetter>()).ToArray();
            activities.Select(a => a.ActivityType).ShouldContain("Kill");
            WritesBack(w => perk.WriteToBinary(w), HeavyWeapons);
        }
    }

    [Fact]
    public void AnimationGraph_ControlsBaseSkeleton()
    {
        foreach (var door in ReadBoth<IDoorGetter>(Record("DOOR", Hex(CageDoor)), f => Door.CreateFromBinary(f), (s, p) => DoorBinaryOverlay.DoorFactory(s, p)))
        {
            Component<IAnimationGraphComponentGetter>(door.Components).ControlsBaseSkeleton.ShouldBeTrue();
            WritesBack(w => door.WriteToBinary(w), CageDoor);
        }
    }

    [Fact]
    public void ObjectWindowFilter_CountedFilters()
    {
        foreach (var lcrt in ReadBoth<ILocationReferenceTypeGetter>(Record("LCRT", Hex(FurnitureLocRefType)), f => LocationReferenceType.CreateFromBinary(f), (s, p) => LocationReferenceTypeBinaryOverlay.LocationReferenceTypeFactory(s, p)))
        {
            Component<IObjectWindowFilterComponentGetter>(lcrt.Components).Filters.ShouldBe(new[] { "" });
            WritesBack(w => lcrt.WriteToBinary(w), FurnitureLocRefType);
        }
    }

    [Fact]
    public void DisplayCase_ExclusionKeywordAndNumber()
    {
        foreach (var cont in ReadBoth<IContainerGetter>(Record("CONT", Hex(RifleCase)), f => Container.CreateFromBinary(f), (s, p) => ContainerBinaryOverlay.ContainerFactory(s, p)))
        {
            var items = Component<IDisplayCaseComponentGetter>(cont.Components).Items;
            items.Count.ShouldBe(3);
            items.ShouldAllBe(i => i.ExclusionFilterKeyword.IsNull && i.Number == 1);
            items.Select(i => i.Index).ShouldBe(new uint[] { 0, 1, 2 });
            WritesBack(w => cont.WriteToBinary(w), RifleCase);
        }
    }

    [Fact]
    public void SpaceshipEquipment_Essential()
    {
        foreach (var gbfm in ReadBoth<IGenericBaseFormGetter>(Record("GBFM", Hex(Scorpius)), f => GenericBaseForm.CreateFromBinary(f), (s, p) => GenericBaseFormBinaryOverlay.GenericBaseFormFactory(s, p)))
        {
            Component<ISpaceshipEquipmentComponentGetter>(gbfm.Components).Essential.ShouldBe(true);
            WritesBack(w => gbfm.WriteToBinary(w), Scorpius);
        }
    }

    [Fact]
    public void Crowd_DensityAndCountedPopulations()
    {
        foreach (var gbfm in ReadBoth<IGenericBaseFormGetter>(Record("GBFM", Hex(Crowd)), f => GenericBaseForm.CreateFromBinary(f), (s, p) => GenericBaseFormBinaryOverlay.GenericBaseFormFactory(s, p)))
        {
            var crowd = Component<ICrowdComponentGetter>(gbfm.Components);
            crowd.Density.ShouldNotBeNull().ShouldBe(0.1f, 0.0001f);
            crowd.PopulationCount.ShouldBe(2u);
            crowd.Items.Select(i => i.Name).ShouldBe(new[] { "CrowdCompNightTime", "CrowdCompDayTime" });
            crowd.Items.Select(i => i.PopulationScale ?? -1f).ShouldBe(new[] { 0.5f, 1f });
            WritesBack(w => gbfm.WriteToBinary(w), Crowd);
        }
    }

    [Fact]
    public void WorldSpaceOverlay_StarSystemAndPlanetIds()
    {
        foreach (var wrld in ReadBoth<IWorldspaceGetter>(Record("WRLD", Hex(Overlay)), f => Worldspace.CreateFromBinary(f), (s, p) => WorldspaceBinaryOverlay.WorldspaceFactory(s, p)))
        {
            var overlay = Component<IWorldSpaceOverlayComponentGetter>(wrld.Components);
            overlay.StarSystemId.ShouldBe(-1);
            overlay.PlanetId.ShouldBe(-1);
            WritesBack(w => wrld.WriteToBinary(w), Overlay);
        }
    }

    [Fact]
    public void AdaptiveTrigger_Effects()
    {
        foreach (var kywd in ReadBoth<IKeywordGetter>(Record("KYWD", Hex(Electromagnetic)), f => Keyword.CreateFromBinary(f), (s, p) => KeywordBinaryOverlay.KeywordFactory(s, p)))
        {
            var trigger = Component<IAdaptiveTriggerDataComponentGetter>(kywd.Components);
            var fire = trigger.FireEffect.ShouldNotBeNull();
            fire.Unused.ShouldBe((byte)0);
            fire.StartPosition.ShouldBe((byte)3);
            fire.EndPosition.ShouldBe((byte)6);
            fire.Strength.ShouldBe((byte)8);
            var ads = trigger.AdsEffect.ShouldNotBeNull();
            ads.StartPosition.ShouldBe((byte)2);
            ads.EndPosition.ShouldBe((byte)6);
            ads.Strength.ShouldBe((byte)3);
            WritesBack(w => kywd.WriteToBinary(w), Electromagnetic);
        }
    }
}
